// DiscountsAvailablePtrFromProto is DiscountsAvailableFromProto for nullable columns:
// unspecified maps to nil.
func DiscountsAvailablePtrFromProto(v codes.DiscountsAvailable) *DiscountsAvailable {
	if s := DiscountsAvailableFromProto(v); s != "" {
		return &s
	}
	return nil
}

// DiscountsAvailablePtrToProto is DiscountsAvailableToProto for nullable columns.
func DiscountsAvailablePtrToProto(v *DiscountsAvailable) codes.DiscountsAvailable {
	if v == nil {
		return 0
	}
	return DiscountsAvailableToProto(*v)
}

