// DisabilityFeatureCodePtrFromProto is DisabilityFeatureCodeFromProto for nullable columns:
// unspecified maps to nil.
func DisabilityFeatureCodePtrFromProto(v codes.DisabilityFeatureCode) *DisabilityFeatureCode {
	if s := DisabilityFeatureCodeFromProto(v); s != "" {
		return &s
	}
	return nil
}

// DisabilityFeatureCodePtrToProto is DisabilityFeatureCodeToProto for nullable columns.
func DisabilityFeatureCodePtrToProto(v *DisabilityFeatureCode) codes.DisabilityFeatureCode {
	if v == nil {
		return 0
	}
	return DisabilityFeatureCodeToProto(*v)
}

